extern "C" __global__ void float_pow(float* x){int i=blockIdx.x*blockDim.x+threadIdx.x;x[i]=powf(x[i],x[i+1]);}
extern "C" __global__ void float_exp(float* x){int i=blockIdx.x*blockDim.x+threadIdx.x;x[i]=expf(x[i]);}
extern "C" __global__ void float_log(float* x){int i=blockIdx.x*blockDim.x+threadIdx.x;x[i]=logf(x[i]);}
extern "C" __global__ void float_mod(float* x){int i=blockIdx.x*blockDim.x+threadIdx.x;x[i]=fmodf(x[i],x[i+1]);}
extern "C" __global__ void float_trig(float* x){int i=blockIdx.x*blockDim.x+threadIdx.x;x[i]=sinf(x[i])+cosf(x[i]);}
